  `version` varchar(32) DEFAULT NULL COMMENT '版本号',
  `publish_date` date DEFAULT NULL COMMENT '发布日期（备案时限与评估周期的起算点）',
  `filing_deadline` date DEFAULT NULL COMMENT '备案截止日（发布 + 20 个工作日，派生值不进表单）',
