  `enterprise_name` varchar(200) NOT NULL COMMENT '排污单位名称(本企业)',
  `issuing_authority` varchar(200) DEFAULT '' COMMENT '发证机关',
  `issue_date` date DEFAULT NULL COMMENT '发证日期',
